<div class="page-head no-print"><div><span class="eyebrow">FACTURATION</span><h1>Facture <?= e($sale['invoice_no']) ?></h1></div><button class="btn primary" onclick="window.print()">Imprimer / PDF</button></div><section class="panel invoice"><div class="invoice-top"><div><span class="brand-icon">F</span><h2><?= e($company['name']) ?></h2><p><?= e($company['address']??'') ?> · <?= e($company['city']??'') ?><br><?= e($company['phone']??'') ?> · IFU : <?= e($company['ifu']??'') ?></p><p>Facture commerciale</p></div><div class="right"><h2><?= e($sale['invoice_no']) ?></h2><p><?= e(date('d/m/Y',strtotime($sale['created_at']))) ?></p></div></div><hr><p><b>Client :</b> <?= e($sale['customer']??'Client comptoir') ?><br><?= e($sale['phone']??'') ?><br><?= e($sale['address']??'') ?></p><table><thead><tr><th>Désignation</th><th>Qté</th><th>Prix unitaire</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?= e($i['product_name']) ?></td><td><?= (int)$i['quantity'] ?></td><td><?= money($i['unit_price']) ?></td><td><?= money($i['line_total']) ?></td></tr><?php endforeach; ?></tbody></table><div class="invoice-total"><p>Sous-total : <?= money($sale['subtotal']??$sale['total']) ?></p><p>TVA : <?= money($sale['tax_amount']??0) ?></p><h2>Total : <?= money($sale['total']) ?></h2></div><p class="muted center">Merci pour votre confiance.</p></section>